1	# Expõe o kong local (54321) publicamente (cloudflared/ngrok). Ver tunnel.sh para detalhes.
2	#   $env:CF_TUNNEL_NAME="darcy"; ./scripts/tunnel.ps1     (túnel nomeado, URL fixa)
3	#   ./scripts/tunnel.ps1                                   (quick tunnel, URL aleatória)
4	param([int]$Port = 54321)
5	$target = "http://127.0.0.1:$Port"
6	
7	if ($env:NGROK_DOMAIN) {
8	  if (-not (Get-Command ngrok -ErrorAction SilentlyContinue)) { Write-Error "ngrok não encontrado."; exit 1 }
9	  Write-Host "==> ngrok $target --domain=$($env:NGROK_DOMAIN)"
10	  ngrok http $Port --domain=$env:NGROK_DOMAIN
11	  return
12	}
13	if (-not (Get-Command cloudflared -ErrorAction SilentlyContinue)) { Write-Error "cloudflared não encontrado."; exit 1 }
14	
15	if ($env:CF_TUNNEL_NAME) {
16	  Write-Host "==> cloudflared named tunnel '$($env:CF_TUNNEL_NAME)' -> $target"
17	  cloudflared tunnel run $env:CF_TUNNEL_NAME
18	} else {
19	  Write-Host "==> cloudflared QUICK tunnel -> $target (URL aleatória trycloudflare.com)"
20	  Write-Host "    Depois: atualize o .env com a URL, rebuild do widget e reseed."
21	  cloudflared tunnel --url $target
22	}
