1	// Sobe widget-src/dist/widget.js para o bucket `ativos` do Supabase LOCAL em execução.
2	// Use APÓS um build, para atualizar o widget sem precisar de `supabase db reset` (que
3	// re-semeia o bucket). O bucket já existe (semeado pelo config.toml no start/reset).
4	//
5	// Requer a service_role key local (impressa por `npx supabase status`):
6	//   SUPABASE_SERVICE_ROLE_KEY=... node scripts/upload-widget.mjs
7	//   (SUPABASE_URL default = http://127.0.0.1:54321)
8	import { readFileSync, existsSync } from 'fs';
9	import { resolve, dirname } from 'path';
10	import { fileURLToPath } from 'url';
11	
12	const __dirname = dirname(fileURLToPath(import.meta.url));
13	const SUPABASE_URL = process.env.SUPABASE_URL || 'http://127.0.0.1:54321';
14	const SERVICE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;
15	
16	if (!SERVICE_KEY) {
17	  console.error('ERRO: defina SUPABASE_SERVICE_ROLE_KEY (veja `npx supabase status`).');
18	  process.exit(1);
19	}
20	
21	const widgetPath = resolve(__dirname, '../widget-src/dist/widget.js');
22	if (!existsSync(widgetPath)) {
23	  console.error(`ERRO: ${widgetPath} não existe. Rode o build primeiro (./scripts/build-widget.sh).`);
24	  process.exit(1);
25	}
26	
27	const body = readFileSync(widgetPath);
28	const url = `${SUPABASE_URL}/storage/v1/object/ativos/widget.js`;
29	const res = await fetch(url, {
30	  method: 'POST',
31	  headers: {
32	    Authorization: `Bearer ${SERVICE_KEY}`,
33	    'x-upsert': 'true',
34	    'Content-Type': 'text/javascript',
35	  },
36	  body,
37	});
38	
39	console.log(`POST ${url} -> ${res.status}`);
40	console.log(await res.text());
41	if (!res.ok) process.exit(1);
42	console.log('OK: widget.js atualizado no bucket `ativos`.');
